create table public.party (id uuid primary key default gen_random_uuid(), office_id uuid not null references public.office(id) on delete restrict, party_type text not null check (party_type in ('person','company','other')), display_name text not null check (char_length(btrim(display_name)) between 2 and 200), normalized_name text not null check (char_length(normalized_name) between 2 and 200), status text not null default 'active' check (status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid not null references public.user_profile(id) on delete restrict, unique(office_id,id));
create index party_name_idx on public.party(office_id,normalized_name); create index party_status_idx on public.party(office_id,status);
create table public.client (id uuid primary key default gen_random_uuid(), office_id uuid not null references public.office(id) on delete restrict, party_id uuid not null, status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid not null references public.user_profile(id) on delete restrict, unique(office_id,id), foreign key(office_id,party_id) references public.party(office_id,id) on delete restrict);
create unique index client_party_active_idx on public.client(office_id,party_id) where status='active'; create index client_status_idx on public.client(office_id,status);
create table public.client_related_party (id uuid primary key default gen_random_uuid(), office_id uuid not null references public.office(id) on delete restrict, client_id uuid not null, party_id uuid not null, relation_type text not null check (char_length(btrim(relation_type)) between 2 and 80), confirmation_status text not null default 'pending' check(confirmation_status in('pending','confirmed','rejected')), confirmed_by uuid references public.user_profile(id) on delete restrict, confirmed_at timestamptz, status text not null default 'active' check(status in('active','inactive')), notes text check(notes is null or char_length(notes)<=1000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid not null references public.user_profile(id) on delete restrict, unique(office_id,id), foreign key(office_id,client_id) references public.client(office_id,id) on delete restrict, foreign key(office_id,party_id) references public.party(office_id,id) on delete restrict, check((confirmation_status='pending' and confirmed_by is null and confirmed_at is null) or (confirmation_status in('confirmed','rejected') and confirmed_by is not null and confirmed_at is not null)));
create unique index relation_active_idx on public.client_related_party(office_id,client_id,party_id,relation_type) where status='active'; create index relation_client_idx on public.client_related_party(office_id,client_id,status);
create or replace function public.write_operational_audit(p_action text,p_entity_type text,p_entity_id uuid,p_metadata jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; aid bigint; begin select * into a from public.require_active_actor(); if p_action not in('client.created','client.updated','client.deactivated','party.created','party.updated','party.deactivated','client_related_party.created','client_related_party.updated','client_related_party.confirmed','client_related_party.rejected','client_related_party.deactivated') then raise exception 'audit action is not allowlisted' using errcode='22023'; end if; if p_metadata is null or jsonb_typeof(p_metadata)<>'object' then raise exception 'invalid audit metadata' using errcode='22023'; end if; insert into public.audit_log(audit_scope,office_id,actor_user_id,action,entity_type,entity_id,metadata) values('operational',a.actor_office_id,a.actor_id,p_action,p_entity_type,p_entity_id,p_metadata) returning id into aid; return aid; end; $$;
create or replace function public.create_client_with_party(p_party_type text,p_display_name text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; pid uuid; cid uuid; n text; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; n:=lower(regexp_replace(btrim(p_display_name),'\\s+',' ','g')); if p_party_type not in('person','company','other') or char_length(n) not between 2 and 200 then raise exception 'invalid input' using errcode='22023'; end if; insert into public.party(office_id,party_type,display_name,normalized_name,created_by) values(a.actor_office_id,p_party_type,btrim(p_display_name),n,a.actor_id) returning id into pid; insert into public.client(office_id,party_id,created_by) values(a.actor_office_id,pid,a.actor_id) returning id into cid; perform public.write_operational_audit('party.created','party',pid,jsonb_build_object('after',jsonb_build_object('party_type',p_party_type,'status','active'))); perform public.write_operational_audit('client.created','client',cid,jsonb_build_object('after',jsonb_build_object('status','active'))); return cid; end; $$;
create or replace function public.create_party(p_party_type text,p_display_name text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; pid uuid; n text; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; n:=lower(regexp_replace(btrim(p_display_name),'\\s+',' ','g')); if p_party_type not in('person','company','other') or char_length(n) not between 2 and 200 then raise exception 'invalid input' using errcode='22023'; end if; insert into public.party(office_id,party_type,display_name,normalized_name,created_by) values(a.actor_office_id,p_party_type,btrim(p_display_name),n,a.actor_id) returning id into pid; perform public.write_operational_audit('party.created','party',pid,jsonb_build_object('after',jsonb_build_object('party_type',p_party_type,'status','active'))); return pid; end; $$;
create or replace function public.create_client_related_party(p_client_id uuid,p_party_id uuid,p_relation_type text,p_notes text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; rid uuid; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; insert into public.client_related_party(office_id,client_id,party_id,relation_type,notes,created_by) values(a.actor_office_id,p_client_id,p_party_id,btrim(p_relation_type),p_notes,a.actor_id) returning id into rid; perform public.write_operational_audit('client_related_party.created','client_related_party',rid,jsonb_build_object('after',jsonb_build_object('confirmation_status','pending','status','active'))); return rid; end; $$;
create or replace function public.confirm_client_related_party(p_relation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; r public.client_related_party%rowtype; begin select * into a from public.require_active_actor(); if a.actor_role<>'lawyer' then raise exception 'permission denied' using errcode='42501'; end if; select * into r from public.client_related_party where id=p_relation_id and office_id=a.actor_office_id for update; if r.id is null or r.status<>'active' or r.confirmation_status<>'pending' then raise exception 'invalid transition' using errcode='P0001'; end if; update public.client_related_party set confirmation_status='confirmed',confirmed_by=a.actor_id,confirmed_at=now(),updated_at=now() where id=r.id; perform public.write_operational_audit('client_related_party.confirmed','client_related_party',r.id,jsonb_build_object('before',jsonb_build_object('confirmation_status','pending'),'after',jsonb_build_object('confirmation_status','confirmed'))); end; $$;
create or replace function public.reject_client_related_party(p_relation_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; r public.client_related_party%rowtype; begin select * into a from public.require_active_actor(); if a.actor_role<>'lawyer' then raise exception 'permission denied' using errcode='42501'; end if; select * into r from public.client_related_party where id=p_relation_id and office_id=a.actor_office_id for update; if r.id is null or r.status<>'active' or r.confirmation_status<>'pending' then raise exception 'invalid transition' using errcode='P0001'; end if; update public.client_related_party set confirmation_status='rejected',confirmed_by=a.actor_id,confirmed_at=now(),updated_at=now() where id=r.id; perform public.write_operational_audit('client_related_party.rejected','client_related_party',r.id,jsonb_build_object('before',jsonb_build_object('confirmation_status','pending'),'after',jsonb_build_object('confirmation_status','rejected'))); end; $$;
create or replace function public.deactivate_client(p_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; update public.client set status='inactive',updated_at=now() where id=p_id and office_id=a.actor_office_id; if not found then raise exception 'not found' using errcode='P0002'; end if; perform public.write_operational_audit('client.deactivated','client',p_id,jsonb_build_object('after',jsonb_build_object('status','inactive'))); end; $$;
create or replace function public.deactivate_party(p_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; update public.party set status='inactive',updated_at=now() where id=p_id and office_id=a.actor_office_id; if not found then raise exception 'not found' using errcode='P0002'; end if; perform public.write_operational_audit('party.deactivated','party',p_id,jsonb_build_object('after',jsonb_build_object('status','inactive'))); end; $$;
create or replace function public.deactivate_client_related_party(p_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; update public.client_related_party set status='inactive',updated_at=now() where id=p_id and office_id=a.actor_office_id; if not found then raise exception 'not found' using errcode='P0002'; end if; perform public.write_operational_audit('client_related_party.deactivated','client_related_party',p_id,jsonb_build_object('after',jsonb_build_object('status','inactive'))); end; $$;
alter table public.party enable row level security; alter table public.client enable row level security; alter table public.client_related_party enable row level security;
revoke all on public.party,public.client,public.client_related_party from public,anon,authenticated,service_role; grant select on public.party,public.client,public.client_related_party to authenticated;
create policy party_select_same_office on public.party for select to authenticated using (office_id=(select office_id from public.user_profile where id=auth.uid() and is_active=true));
create policy client_select_same_office on public.client for select to authenticated using (office_id=(select office_id from public.user_profile where id=auth.uid() and is_active=true));
create policy relation_select_same_office on public.client_related_party for select to authenticated using (office_id=(select office_id from public.user_profile where id=auth.uid() and is_active=true));
revoke all on function public.write_operational_audit(text,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.create_client_with_party(text,text),public.create_party(text,text),public.create_client_related_party(uuid,uuid,text,text),public.confirm_client_related_party(uuid),public.reject_client_related_party(uuid),public.deactivate_client(uuid),public.deactivate_party(uuid),public.deactivate_client_related_party(uuid) to authenticated;
create or replace function public.update_client(p_id uuid,p_status text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; old_status text; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; select status into old_status from public.client where id=p_id and office_id=a.actor_office_id for update; if old_status is null or p_status is null or p_status not in('active','inactive') then raise exception 'invalid input' using errcode='22023'; end if; update public.client set status=p_status,updated_at=now() where id=p_id and office_id=a.actor_office_id; perform public.write_operational_audit('client.updated','client',p_id,jsonb_build_object('before',jsonb_build_object('status',old_status),'after',jsonb_build_object('status',p_status))); end; $$;
create or replace function public.update_party(p_id uuid,p_display_name text,p_party_type text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare a record; old_name text; old_type text; n text; begin select * into a from public.require_active_actor(); if a.actor_role not in('lawyer','operator') then raise exception 'permission denied' using errcode='42501'; end if; n:=lower(regexp_replace(btrim(p_display_name),'\\s+',' ','g')); if p_party_type not in('person','company','other') or char_length(n) not between 2 and 200 then raise exception 'invalid input' using errcode='22023'; end if; select display_name,party_type into old_name,old_type from public.party where id=p_id and office_id=a.actor_office_id for update; if old_name is null then raise exception 'not found' using errcode='P0002'; end if; update public.party set display_name=btrim(p_display_name),normalized_name=n,party_type=p_party_type,updated_at=now() where id=p_id and office_id=a.actor_office_id; perform public.write_operational_audit('party.updated','party',p_id,jsonb_build_object('before',jsonb_build_object('party_type',old_type),'after',jsonb_build_object('party_type',p_party_type))); end; $$;
grant execute on function public.update_client(uuid,text),public.update_party(uuid,text,text) to authenticated;
